package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.sql.Timestamp;import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.json.JsonMapper;
import io.knowledgebrain.contracts.collaboration.discussion.v1.*;
/** Shared Study conversation. Original text and replies are immutable; moderation is versioned. */
final class DiscussionStore {
 record Discussion(UUID discussionId,UUID studyId,UUID groupId,UUID spaceId,UUID creatorId,long version,String title,String description,String state,String audience,String createdAt,String updatedAt) {}
 record Summary(UUID discussionId,UUID creatorId,long version,String title,String state) {}
 record Page(List<Summary> items,UUID nextAfter,boolean studyArchived) {}
 record Revision(UUID revisionId,long version,UUID actorId,String occurredAt,Discussion snapshot) {}
 record History(List<Revision> items,Long nextBefore) {}
 record Result(Discussion discussion,boolean created) {}
 record Reply(UUID replyId,UUID discussionId,UUID studyId,UUID groupId,UUID spaceId,UUID authorId,long version,long discussionVersion,String content,String audience,String createdAt) {}
 record Replies(List<Reply> items,UUID nextAfter) {}
 record ReplyResult(Reply reply,boolean created) {}
 private final JdbcTemplate sql;private final TransactionTemplate tx;private final StudyStore studies;private final Clock clock;private final UuidV7 ids;private final JsonMapper json=JsonMapper.builder().build();
 DiscussionStore(DataSource source,StudyStore studies,Clock clock){sql=new JdbcTemplate(source);tx=new TransactionTemplate(new DataSourceTransactionManager(source));tx.setTimeout(15);this.studies=studies;this.clock=clock;ids=new UuidV7(clock);}
 private static ResponseStatusException error(HttpStatus s,String message){return new ResponseStatusException(s,message);}
 private String now(){return clock.instant().truncatedTo(ChronoUnit.MICROS).toString();}
 private void validate(UUID group,UUID space,UUID study,UUID actor,String trace){for(var id:List.of(group,space,study,actor))GroupInput.id(id.toString());if(trace==null||!trace.matches("[0-9a-f]{32}")||trace.equals("0".repeat(32)))throw GroupInput.bad();}
 private void key(String key){if(key==null||!key.matches("[0-9a-f]{32}"))throw GroupInput.bad();}
 private void writable(StudyStore.Study parent){if(parent.state().equals("RETIRED"))throw error(HttpStatus.CONFLICT,"Study is archived");}
 Discussion get(UUID group,UUID space,UUID study,UUID id){return get(group,space,study,id,false);}
 private Discussion get(UUID group,UUID space,UUID study,UUID id,boolean lock){var rows=sql.query("SELECT snapshot::text FROM study_discussion WHERE group_id=? AND space_id=? AND study_id=? AND discussion_id=?"+(lock?" FOR UPDATE":""),(rs,n)->json.readValue(rs.getString(1),Discussion.class),group,space,study,id);if(rows.size()!=1)throw error(HttpStatus.NOT_FOUND,"Discussion unavailable");return rows.getFirst();}
 Page list(UUID group,UUID space,UUID study,UUID after,int limit){var parent=studies.get(group,space,study);var rows=sql.query("SELECT discussion_id,creator_id,version,title,state FROM study_discussion WHERE group_id=? AND space_id=? AND study_id=?"+(after==null?"":" AND discussion_id>?")+" ORDER BY discussion_id LIMIT ?",(rs,n)->new Summary(rs.getObject(1,UUID.class),rs.getObject(2,UUID.class),rs.getLong(3),rs.getString(4),rs.getString(5)),after==null?new Object[]{group,space,study,limit+1}:new Object[]{group,space,study,after,limit+1});var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new Page(items,rows.size()>limit?items.getLast().discussionId():null,parent.state().equals("RETIRED"));}
 History history(UUID group,UUID space,UUID study,UUID id,long before,int limit){get(group,space,study,id);var rows=sql.query("SELECT revision_id,version,actor_id,occurred_at,snapshot::text FROM study_discussion_revision WHERE discussion_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new Revision(rs.getObject(1,UUID.class),rs.getLong(2),rs.getObject(3,UUID.class),rs.getTimestamp(4).toInstant().toString(),json.readValue(rs.getString(5),Discussion.class)),id,before,limit+1);var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new History(items,rows.size()>limit?items.getLast().version():null);}
 Result create(UUID group,UUID space,UUID study,UUID actor,String key,String title,String description,String trace){
  validate(group,space,study,actor,trace);key(key);if(title==null||description==null)throw GroupInput.bad();GroupInput.settings(json.writeValueAsBytes(Map.of("title",title,"description",description)));
  return tx.execute(s->{var parent=studies.lockForChild(group,space,study);var prior=sql.query("SELECT creation_title,creation_description,snapshot::text FROM study_discussion WHERE study_id=? AND creator_id=? AND request_key=?",(rs,n)->{if(!rs.getString(1).equals(title)||!rs.getString(2).equals(description))throw error(HttpStatus.CONFLICT,"Discussion key already used");return json.readValue(rs.getString(3),Discussion.class);},study,actor,key);if(!prior.isEmpty())return new Result(prior.getFirst(),false);writable(parent);
   String now=now();var v=new Discussion(ids.next(),study,group,space,actor,1,title,description,"OPEN","GROUP_MEMBERS",now,now);
   sql.update("INSERT INTO study_discussion (discussion_id,study_id,group_id,space_id,creator_id,request_key,creation_title,creation_description,version,title,state,snapshot) VALUES (?,?,?,?,?,?,?,?,?,?,?,?::jsonb)",v.discussionId(),study,group,space,actor,key,title,description,1,title,"OPEN",json.writeValueAsString(v));record(v,actor,trace,"DiscussionCreated");return new Result(v,true);
  });
 }
 Discussion state(UUID group,UUID space,UUID study,UUID id,UUID actor,long expected,String target,String trace){
  validate(group,space,study,actor,trace);GroupInput.id(id.toString());if(expected<1||target==null||!Set.of("OPEN","LOCKED","RETIRED").contains(target))throw GroupInput.bad();
  return tx.execute(s->{var parent=studies.lockForChild(group,space,study);var old=get(group,space,study,id,true);if(old.version()!=expected)throw error(HttpStatus.PRECONDITION_FAILED,"Discussion changed; refresh current version");if(old.state().equals(target))return old;writable(parent);if(old.state().equals("RETIRED"))throw error(HttpStatus.CONFLICT,"Discussion is archived");
   var v=new Discussion(id,study,group,space,old.creatorId(),Math.addExact(old.version(),1),old.title(),old.description(),target,"GROUP_MEMBERS",old.createdAt(),now());sql.update("UPDATE study_discussion SET version=?,state=?,snapshot=?::jsonb WHERE discussion_id=?",v.version(),target,json.writeValueAsString(v),id);record(v,actor,trace,target.equals("RETIRED")?"DiscussionRetired":"DiscussionStateChanged");return v;
  });
 }
 static String content(byte[] bytes){var v=GroupInput.json(bytes);if(v==null||!v.isObject()||v.size()!=1||!v.path("content").isString())throw GroupInput.bad();String content=v.path("content").asString();content(content);return content;}
 private static void content(String content){if(content==null||content.isBlank()||!GroupInput.unicode(content)||content.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>32768)throw GroupInput.bad();}
 ReplyResult reply(UUID group,UUID space,UUID study,UUID discussion,UUID actor,long expected,String key,String content,String trace){
  validate(group,space,study,actor,trace);GroupInput.id(discussion.toString());key(key);content(content);if(expected<1)throw GroupInput.bad();
  return tx.execute(s->{var parent=studies.lockForChild(group,space,study);var topic=get(group,space,study,discussion,true);var prior=sql.query("SELECT snapshot::text FROM discussion_reply WHERE discussion_id=? AND author_id=? AND request_key=?",(rs,n)->{var v=json.readValue(rs.getString(1),Reply.class);if(v.discussionVersion()!=expected||!v.content().equals(content))throw error(HttpStatus.CONFLICT,"Reply key already used");return v;},discussion,actor,key);if(!prior.isEmpty())return new ReplyResult(prior.getFirst(),false);
   writable(parent);if(!topic.state().equals("OPEN"))throw error(HttpStatus.CONFLICT,"Discussion is not open");if(topic.version()!=expected)throw error(HttpStatus.PRECONDITION_FAILED,"Discussion changed; refresh before replying");
   var v=new Reply(ids.next(),discussion,study,group,space,actor,1,expected,content,"GROUP_MEMBERS",now());sql.update("INSERT INTO discussion_reply (reply_id,discussion_id,study_id,group_id,space_id,author_id,request_key,discussion_version,snapshot) VALUES (?,?,?,?,?,?,?,?,?::jsonb)",v.replyId(),discussion,study,group,space,actor,key,expected,json.writeValueAsString(v));record(v,trace);return new ReplyResult(v,true);
  });
 }
 Reply getReply(UUID group,UUID space,UUID study,UUID discussion,UUID reply){var rows=sql.query("SELECT snapshot::text FROM discussion_reply WHERE group_id=? AND space_id=? AND study_id=? AND discussion_id=? AND reply_id=?",(rs,n)->json.readValue(rs.getString(1),Reply.class),group,space,study,discussion,reply);if(rows.size()!=1)throw error(HttpStatus.NOT_FOUND,"Reply unavailable");return rows.getFirst();}
 Replies replies(UUID group,UUID space,UUID study,UUID discussion,UUID after,int limit){get(group,space,study,discussion);var rows=sql.query("SELECT snapshot::text FROM discussion_reply WHERE discussion_id=?"+(after==null?"":" AND reply_id>?")+" ORDER BY reply_id LIMIT ?",(rs,n)->json.readValue(rs.getString(1),Reply.class),after==null?new Object[]{discussion,limit+1}:new Object[]{discussion,after,limit+1});var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new Replies(items,rows.size()>limit?items.getLast().replyId():null);}
 private void record(Discussion v,UUID actor,String trace,String type){
  sql.update("INSERT INTO study_discussion_revision (revision_id,discussion_id,version,actor_id,occurred_at,snapshot) VALUES (?,?,?,?,?,?::jsonb)",ids.next(),v.discussionId(),v.version(),actor,Timestamp.from(Instant.parse(v.updatedAt())),json.writeValueAsString(v));
  var payload=DiscussionSnapshotV1.newBuilder().setDiscussionId(v.discussionId().toString()).setStudyId(v.studyId().toString()).setGroupId(v.groupId().toString()).setSpaceId(v.spaceId().toString()).setCreatorId(v.creatorId().toString()).setVersion(v.version()).setTitle(v.title()).setDescription(v.description()).setState(v.state()).setAudience(v.audience()).setCreatedAt(v.createdAt()).setUpdatedAt(v.updatedAt()).build().toByteString();event(v.discussionId(),v.spaceId(),actor,trace,v.updatedAt(),"discussion","Discussion",type,payload);
 }
 private void record(Reply v,String trace){var payload=DiscussionReplySnapshotV1.newBuilder().setReplyId(v.replyId().toString()).setDiscussionId(v.discussionId().toString()).setStudyId(v.studyId().toString()).setGroupId(v.groupId().toString()).setSpaceId(v.spaceId().toString()).setAuthorId(v.authorId().toString()).setVersion(v.version()).setDiscussionVersion(v.discussionVersion()).setContent(v.content()).setAudience(v.audience()).setCreatedAt(v.createdAt()).build().toByteString();event(v.replyId(),v.spaceId(),v.authorId(),trace,v.createdAt(),"discussion-reply","DiscussionReply","DiscussionReplyCreated",payload);}
 private void event(UUID aggregate,UUID space,UUID actor,String trace,String at,String route,String kind,String type,com.google.protobuf.ByteString payload){UUID id=ids.next();var e=DiscussionEnvelopeV1.newBuilder().setEventId(id.toString()).setEventType(type).setEventVersion(1).setOccurredAtEpochMillis(Instant.parse(at).toEpochMilli()).setProducer("collaboration-service").setAggregateType(kind).setAggregateId(aggregate.toString()).setSpaceId(space.toString()).setActorId(actor.toString()).setTraceId(trace).setPayload(payload).build();sql.update("INSERT INTO outbox_event VALUES (?,?,?,?,?,?,'collaboration','discussion-events','1',?)",id,route,aggregate,type,Timestamp.from(Instant.parse(at)),trace,e.toByteArray());}
}
